mapper.update:
UPDATE `credit_account`
SET available = available - #{credits},
    frozen = frozen + #{credits}
WHERE user_id = #{userId}

UPDATE `credit_account`
SET frozen = frozen - #{held},
    available = available + (#{held} - #{actual}),
    total_consumed = total_consumed + #{actual}
WHERE user_id = #{userId}

UPDATE `credit_account`
SET frozen = frozen - #{held},
    available = available + #{held}
WHERE user_id = #{userId}

UPDATE `credit_account`
SET available = available + #{amount}
WHERE user_id = #{userId}
